export function projectPageDetail(
  root: ReturnType<typeof pageAri>,
  contentMap: ContentMap<ContentRegistry>,
  args: {
    params: PageDetailParams;
    executionContext: PageDetailExecutionContext;
    redirects: ReadonlyMap<ResourceKey, ApplicationResourceIdentifier>;
  }
): PageDetailResult {
  const memo = new Map<string, object>();

  const projectOnPage = (resource: any, payload: any): any => {
    const shell: any = {};
    memo.set(resource.toString(), shell);
    shell.id = payload.id;
    shell.title = payload.title;
    shell.menu = projectNode(
      entryAri({
        spaceId: resource.key[0].spaceId,
        environmentId: resource.key[0].environmentId,
        id: payload.menuId,
        locale: resource.key[0].locale,
      })
    );
    shell.footer = projectNode(
      entryAri({
        spaceId: resource.key[0].spaceId,
        environmentId: resource.key[0].environmentId,
        id: payload.footerId,
        locale: resource.key[0].locale,
      })
    );
    shell.strips = payload.strips.map((link: any) =>
      projectNode(
        entryAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: link.id,
          locale: resource.key[0].locale,
        })
      )
    );
    shell.related = payload.related.map((ref: any) =>
      projectNode(customReferenceAri({ ref: ref, locale: resource.key[0].locale }))
    );
    return shell;
  };

  const projectOnEntry = (resource: any, payload: any): any => {
    if (payload.kind == "Hero") {
      const shell: any = {};
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      shell.image = projectNode(
        assetAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: payload.imageId,
          locale: resource.key[0].locale,
        })
      );
      return shell;
    } else if (payload.kind == "Tabs") {
      const shell: any = {};
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      shell.tabs = payload.tabs.map((link: any) =>
        projectNode(
          entryAri({
            spaceId: resource.key[0].spaceId,
            environmentId: resource.key[0].environmentId,
            id: link.id,
            locale: resource.key[0].locale,
          })
        )
      );
      return shell;
    } else if (payload.kind == "Tab") {
      const shell: any = {};
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      shell.strips = payload.strips.map((link: any) =>
        projectNode(
          entryAri({
            spaceId: resource.key[0].spaceId,
            environmentId: resource.key[0].environmentId,
            id: link.id,
            locale: resource.key[0].locale,
          })
        )
      );
      return shell;
    } else if (payload.kind == "Menu") {
      const shell: any = {};
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.title = payload.title;
      shell.logo = projectNode(
        assetAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: payload.logoId,
          locale: resource.key[0].locale,
        })
      );
      return shell;
    } else if (payload.kind == "Footer" && !payload.id) {
      const shell: any = {};
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.cta = payload.cta;
      shell.title = payload.title;
      return shell;
    } else if (payload.kind == "Footer") {
      const shell: any = {};
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.cta = payload.cta;
      shell.title = payload.title;
      return shell;
    } else if (payload.kind == "SiteInternalLink") {
      const shell: any = {};
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      shell.target = projectNode(
        entryAri({
          spaceId: resource.key[0].spaceId,
          environmentId: resource.key[0].environmentId,
          id: payload.targetId,
          locale: resource.key[0].locale,
        })
      );
      return shell;
    } else {
      const shell: any = {};
      memo.set(resource.toString(), shell);
      shell.kind = payload.kind;
      shell.id = payload.id;
      return shell;
    }
  };

  const projectOnAsset = (resource: any, payload: any): any => {
    const shell: any = {};
    memo.set(resource.toString(), shell);
    shell.kind = payload.kind;
    shell.id = payload.id;
    shell.url = payload.url;
    shell.title = payload.title;
    shell.asset_type = payload.asset_type;
    return shell;
  };

  const projectNode = (ari: any): unknown => {
    const key = ari.toString();
    if (memo.has(key)) return memo.get(key);
    const payload = contentMap.get(ari as never);
    if (payload === undefined) return undefined;
    switch (ari.type) {
      case "Page":
        return projectOnPage(ari, payload);
      case "Entry":
        return projectOnEntry(ari, payload);
      case "Asset":
        return projectOnAsset(ari, payload);
      case "CustomReference": {
        const canonical = args.redirects.get(ari.toString());
        if (canonical === undefined) return undefined;
        return projectNode(canonical);
      }
      default:
        throw new Error("projectPageDetail: unexpected resource type " + JSON.stringify(ari.type));
    }
  };

  return projectNode(root) as PageDetailResult;
}

export type ResolvePageDetailInput = {
  params: PageDetailParams;
  sources: readonly DataSource<ContentRegistry, PageDetailExecutionContext>[];
  schedulingMode?: SchedulingMode;
  observer?: ResolutionObserver;
  root: ReturnType<typeof pageAri>;
  executionContext: PageDetailExecutionContext;
  missingResourceMode: MissingResourceMode;
  backingResources?: ReadonlyMap<ResourceKey, unknown>;
  signal?: AbortSignal;
};

export type ResolvePageDetailResult = {
  pageDetail: PageDetailResult;
  contentMap: ContentMap<ContentRegistry>;
  islands: IslandMap;
  islandDependencies: IslandDependencyMap;
  errors: readonly ResolutionError[];
  promotedResourceKeys: readonly ResourceKey[];
};

export async function resolvePageDetail(
  input: ResolvePageDetailInput
): Promise<ResolvePageDetailResult> {
  const resolver = createResourceGraphResolver<ContentRegistry, PageDetailExecutionContext>({
    sources: input.sources,
    strategy: createPageDetailStrategy(input.params).build(),
    schedulingMode: input.schedulingMode,
    observer: input.observer,
  });

  const { contentMap, islands, islandDependencies, errors, promotedResourceKeys, redirects } =
    await resolver.resolve({
      roots: [input.root],
      executionContext: input.executionContext,
      missingResourceMode: input.missingResourceMode,
      backingResources: input.backingResources,
      signal: input.signal,
    });

  const pageDetail = projectPageDetail(input.root, contentMap, {
    params: input.params,
    executionContext: input.executionContext,
    redirects,
  });

  return {
    pageDetail,
    contentMap,
    islands,
    islandDependencies,
    errors,
    promotedResourceKeys,
  };
}
